dfs.template:
# graph/grid flood fill:
def dfs(node):
  if node visited or invalid: return
  mark visited
  for nb in neighbors(node): dfs(nb)
# backtracking: choose -> explore -> unchoose
def backtrack(state):
  if complete: result.append(copy(path)); return
  for choice in valid_choices(state):
    make choice
    backtrack(next_state)
    undo choice

intervals.template:
sort intervals by start
merged=[]
for iv in intervals:
  if merged and iv.start <= merged[-1].end:
    merged[-1].end = max(merged[-1].end, iv.end)   # overlap -> extend
  else:
    merged.append(iv)                              # gap -> new interval

