stack_queue.template:
# stack: matching parentheses
stack=[]
for ch in s:
  if ch is opener: stack.append(ch)
  else:
    if not stack or not matches(stack.pop(), ch): return False
return not stack
# queue underpins BFS (process in arrival order)

matrix.template:
dirs = [(1,0),(-1,0),(0,1),(0,-1)]
def dfs(r,c):
  if out of bounds or invalid: return
  mark visited
  for dr,dc in dirs: dfs(r+dr, c+dc)

bst.template:
# search / insert reuse the same 'go left or right' pruning:
def search(node, target):
  if not node or node.val==target: return node
  return search(node.left,target) if target<node.val else search(node.right,target)
def insert(node, val):
  if not node: return Node(val)
  if val<node.val: node.left=insert(node.left,val)
  else: node.right=insert(node.right,val)
  return node
# validate with an inherited (low,high) range:
def valid(node, low, high):
  if not node: return True
  if not (low < node.val < high): return False
  return valid(node.left,low,node.val) and valid(node.right,node.val,high)

tries.template:
class Node: children={}; is_end=False
def insert(root, word):
  cur=root
  for ch in word:
    cur=cur.children.setdefault(ch, Node())
  cur.is_end=True
def search(root, word, prefix_only=False):
  cur=root
  for ch in word:
    if ch not in cur.children: return False
    cur=cur.children[ch]
  return True if prefix_only else cur.is_end

union_find.template:
parent=list(range(n))
def find(x):
  while parent[x]!=x:
    parent[x]=parent[parent[x]]   # path compression
    x=parent[x]
  return x
def union(a,b):
  ra,rb=find(a),find(b)
  if ra==rb: return False   # already connected (a cycle if this was a new edge)
  parent[ra]=rb
  return True
